package com.hyperosa5pro;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
public class ThemesActivity extends Activity{
 int[] colors={0xFF5478F5,0xFF8B6CF6,0xFF18A999,0xFFEA6C8B,0xFFF09B38,0xFF2689D8,0xFF4D9B61,0xFFDB5960,0xFF2EAFD0,0xFF7777AA,0xFF111111,0xFF8A684C,0xFFDF72BD,0xFF6A8B9F,0xFFB1A442,0xFF3E63B8,0xFF24A17A,0xFFC26C50,0xFF596579,0xFF9B83D6};
 int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(22));return d;}
 public void onCreate(Bundle b){super.onCreate(b);boolean dark=ThemeStore.dark(this);int bg=dark?0xFF0D0F13:0xFFF4F5F9,fg=dark?Color.WHITE:0xFF17191F,card=dark?0xFF202228:Color.WHITE;LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(25),dp(18),dp(12));root.setBackgroundColor(bg);setContentView(root);TextView title=new TextView(this);title.setText("‹   Temas");title.setTextSize(28);title.setTypeface(null,1);title.setTextColor(fg);title.setOnClickListener(v->finish());root.addView(title);TextView sub=new TextView(this);sub.setText("Elige el color de tu HyperOS");sub.setTextSize(14);sub.setTextColor(0xFF858A96);root.addView(sub);ScrollView sc=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 for(int i=0;i<colors.length;i+=2){LinearLayout rr=new LinearLayout(this);for(int j=i;j<Math.min(i+2,colors.length);j++){final int c=colors[j];LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setPadding(dp(12),dp(12),dp(12),dp(12));item.setBackground(shape(card));View dot=new View(this);dot.setBackground(shape(c));item.addView(dot,new LinearLayout.LayoutParams(-1,dp(52)));TextView name=new TextView(this);name.setText(String.format("#%06X",c&0xFFFFFF)+(ThemeStore.get(this,"accent",0xFF5478F5)==c?" ✓":""));name.setTextColor(fg);name.setTextSize(14);name.setPadding(0,dp(9),0,dp(2));item.addView(name);item.setOnClickListener(v->{ThemeStore.set(this,"accent",c);Toast.makeText(this,"Color aplicado al volver al inicio",Toast.LENGTH_SHORT).show();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(4),dp(6),dp(4),dp(6));rr.addView(item,p);}list.addView(rr);}
 }
}
